// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != actor); // wide domain: exclude only the degenerate case where the bug is invisible
        // admin of c is its deployer (setUp's msg.sender = this test contract)
        vm.prank(address(this));
        bool ok = c.setOwner(newOwner);
        assertTrue(ok && c.owner() == newOwner);
    }
}
